-- Tạo ngày 2026-11-05. File này ghi lại toàn bộ nội dung đã được viết lại và
-- áp dụng lên database thật (Supabase project qvsrkxnqeylwtyggyxlv):
--   - 10 công thức: mô tả đầy đủ, nguyên liệu định lượng chuẩn, 6-9 bước nấu
--     chi tiết có thời gian, mức lửa và mẹo thực tế (nấu theo được ngoài đời).
--   - 5 khóa học: mô tả và mô tả chi tiết đầy đủ; bật co_bai_tap cho tất cả.
--   - 15 bài học: tiêu đề riêng theo từng khóa, mô tả 4-6 câu và 3 câu hỏi
--     trắc nghiệm/bài (tổng 45 câu, mỗi câu 10 điểm).
-- Các câu UPDATE chạy theo slug (công thức) và id (khóa học, bài học) nên
-- chạy lại nhiều lần vẫn an toàn (idempotent). Chạy file này trong
-- Supabase SQL Editor hoặc psql sau khi đã có dữ liệu gốc trong bảng.
-- ============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- 1) CÔNG THỨC (10 món)
-- ---------------------------------------------------------------------------
UPDATE cong_thuc SET mo_ta = 'Phở bò Hà Nội chuẩn vị với nước dùng trong veo, thơm nức mùi hành gừng nướng và hoa hồi, quế. Công thức hướng dẫn từ khâu chần xương, ninh nước dùng liu riu đến cách trụng bánh và xếp tô, để bạn nấu được tô phở thanh ngọt tự nhiên, thịt bò mềm thơm ngay tại căn bếp nhà mình.', nguyen_lieu = '[{"ten": "Xương ống bò", "so_luong": 1, "don_vi": "kg"}, {"ten": "Thịt bò nạm (hoặc gầu)", "so_luong": 500, "don_vi": "g"}, {"ten": "Thịt bò thăn (làm tái)", "so_luong": 300, "don_vi": "g"}, {"ten": "Bánh phở tươi", "so_luong": 1, "don_vi": "kg"}, {"ten": "Hành tây (nướng)", "so_luong": 2, "don_vi": "củ"}, {"ten": "Gừng tươi", "so_luong": 80, "don_vi": "g"}, {"ten": "Hoa hồi", "so_luong": 4, "don_vi": "cái"}, {"ten": "Quế thanh", "so_luong": 10, "don_vi": "g"}, {"ten": "Thảo quả", "so_luong": 2, "don_vi": "quả"}, {"ten": "Đinh hương", "so_luong": 5, "don_vi": "nụ"}, {"ten": "Hạt mùi (hạt ngò)", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Nước lọc", "so_luong": 4, "don_vi": "lít"}, {"ten": "Nước mắm ngon", "so_luong": 3, "don_vi": "thìa canh"}, {"ten": "Muối", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Đường phèn", "so_luong": 20, "don_vi": "g"}, {"ten": "Hành lá", "so_luong": 5, "don_vi": "cây"}, {"ten": "Ngò gai (mùi tàu)", "so_luong": 30, "don_vi": "g"}, {"ten": "Rau mùi (ngò rí)", "so_luong": 50, "don_vi": "g"}, {"ten": "Hành tây thái mỏng", "so_luong": 100, "don_vi": "g"}, {"ten": "Giá đỗ", "so_luong": 200, "don_vi": "g"}, {"ten": "Húng quế", "so_luong": 50, "don_vi": "g"}, {"ten": "Chanh", "so_luong": 2, "don_vi": "quả"}, {"ten": "Ớt tươi", "so_luong": 3, "don_vi": "quả"}, {"ten": "Tiêu xay", "so_luong": 1, "don_vi": "thìa cà phê"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Sơ chế xương và thịt: rửa xương ống và thịt nạm với nước muối loãng, ngâm 15 phút rồi rửa lại. Cho xương vào nồi nước lạnh, đun sôi 5 phút để ra hết bọt bẩn, đổ bỏ nước đầu, rửa xương và nồi thật sạch. Đây là bước quan trọng nhất giúp nước dùng trong."}, {"thu_tu": 2, "noi_dung": "Nướng hành tây và gừng trực tiếp trên bếp (hoặc trong lò 200°C khoảng 10 phút) đến khi vỏ cháy xém thơm, cạo bỏ phần cháy đen, đập dập gừng. Rang hoa hồi, quế, thảo quả, đinh hương, hạt mùi trên chảo khô lửa nhỏ 2-3 phút đến dậy mùi, cho vào túi vải cột chặt."}, {"thu_tu": 3, "noi_dung": "Ninh nước dùng: cho 4 lít nước lạnh, xương và thịt nạm vào nồi lớn, đun sôi rồi hớt bọt thật kỹ. Hạ lửa nhỏ nhất để nước chỉ liu riu, không sôi bùng (sôi mạnh sẽ làm nước đục). Ninh tổng cộng 2,5-3 giờ, thỉnh thoảng hớt bọt và lớp mỡ thừa."}, {"thu_tu": 4, "noi_dung": "Sau 60-75 phút, vớt thịt nạm ra ngâm ngay vào thau nước lạnh 10 phút để thịt săn và không bị khô, sau đó bọc lại để nguội, khi ăn thái lát mỏng ngang thớ. Cho túi gia vị cùng hành, gừng nướng vào nồi nước dùng trong 45 phút cuối, tránh cho sớm vì gia vị ngâm lâu sẽ làm nước bị nồng và hơi đắng."}, {"thu_tu": 5, "noi_dung": "Nêm nước dùng: vớt túi gia vị ra, nêm 1 thìa canh muối, 20g đường phèn và 3 thìa canh nước mắm. Vị nước dùng phở cần thanh, ngọt hậu từ xương và hơi nhạt hơn khẩu vị ăn cơm một chút. Giữ nồi nước dùng luôn sôi nhẹ trên bếp."}, {"thu_tu": 6, "noi_dung": "Chuẩn bị thịt tái: cho thịt thăn vào ngăn đá 30 phút cho cứng mặt rồi thái lát thật mỏng ngang thớ. Ướp nhẹ với 1 thìa cà phê nước mắm, chút gừng băm và tiêu, để 10 phút."}, {"thu_tu": 7, "noi_dung": "Trụng bánh phở: đun một nồi nước sôi riêng, cho từng phần bánh phở vào trụng 15-20 giây đến khi sợi mềm nhưng vẫn còn độ dai, vớt ra xóc thật ráo nước rồi cho vào tô đã tráng qua nước nóng."}, {"thu_tu": 8, "noi_dung": "Xếp tô và chan nước: xếp thịt nạm thái lát và thịt tái lên trên bánh phở, thêm phần trắng hành lá chẻ, ngò gai, rau mùi thái nhỏ và hành tây thái mỏng. Chan nước dùng đang sôi già ngập mặt tô để thịt tái chín hồng vừa tới. Rắc chút tiêu xay."}, {"thu_tu": 9, "noi_dung": "Thưởng thức và bảo quản: ăn kèm giá đỗ, húng quế, chanh, ớt và tương ớt, tương đen tùy thích. Nước dùng còn thừa để nguội, hớt sạch mỡ, chia hộp cấp đông dùng được 1 tháng; khi dùng lại chỉ cần đun sôi và nêm nếm lại."}]'::jsonb WHERE slug = 'pho-bo-ha-noi';
UPDATE cong_thuc SET mo_ta = 'Bún chả Hà Nội với chả miếng và chả viên nướng thơm mùi sả, cháy cạnh nhẹ, chan trong bát nước chấm chua ngọt ấm nóng cùng đu đủ cà rốt giòn. Công thức chia rõ phần ướp thịt, nướng thịt và pha nước chấm đúng tỉ lệ để bạn làm được bữa bún chả chuẩn vị phố cổ tại nhà.', nguyen_lieu = '[{"ten": "Thịt ba chỉ (làm chả miếng)", "so_luong": 400, "don_vi": "g"}, {"ten": "Thịt vai heo xay (làm chả viên)", "so_luong": 300, "don_vi": "g"}, {"ten": "Bún tươi", "so_luong": 800, "don_vi": "g"}, {"ten": "Sả băm", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Tỏi băm", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Hành tím băm", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Nước mắm (ướp thịt)", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Đường (thắng nước hàng)", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Mật ong", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Dầu hào", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Dầu ăn", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Tiêu xay", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Nước ấm (pha nước chấm)", "so_luong": 300, "don_vi": "ml"}, {"ten": "Nước mắm (pha nước chấm)", "so_luong": 4, "don_vi": "thìa canh"}, {"ten": "Đường (pha nước chấm)", "so_luong": 3, "don_vi": "thìa canh"}, {"ten": "Giấm gạo", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Đu đủ xanh bào sợi", "so_luong": 100, "don_vi": "g"}, {"ten": "Cà rốt bào sợi", "so_luong": 100, "don_vi": "g"}, {"ten": "Ớt tươi", "so_luong": 2, "don_vi": "quả"}, {"ten": "Rau sống tổng hợp (xà lách, tía tô, kinh giới, húng)", "so_luong": 300, "don_vi": "g"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Thắng nước hàng: cho 2 thìa canh đường vào chảo khô, đun lửa vừa đến khi đường tan chảy và chuyển màu cánh gián thì tắt bếp, thêm 2 thìa canh nước nóng khuấy đều. Nước hàng giúp chả nướng lên màu nâu bóng đẹp và thơm mùi caramel."}, {"thu_tu": 2, "noi_dung": "Ướp thịt: ba chỉ thái miếng mỏng vừa ăn; thịt xay để riêng. Ướp cả hai loại với sả băm, tỏi băm, hành tím băm, 2 thìa canh nước mắm, nước hàng, mật ong, dầu hào, dầu ăn và tiêu. Trộn đều, bọc kín, ướp tối thiểu 30 phút trong ngăn mát (ngon nhất 2 giờ) cho thấm gia vị."}, {"thu_tu": 3, "noi_dung": "Nặn chả viên: chia thịt xay thành các viên khoảng 25g, ấn dẹt nhẹ. Để chả viên nghỉ 10 phút cho săn mặt, khi nướng không bị vỡ."}, {"thu_tu": 4, "noi_dung": "Nướng chả: ngon nhất là nướng than hoa lửa vừa, trở đều tay đến khi chả chín vàng, rìa hơi cháy xém và tươm mỡ thơm. Nếu dùng nồi chiên không dầu: nướng 200°C trong 12-15 phút, lật mặt ở giữa chừng; với lò nướng: 220°C khoảng 18-20 phút. Nướng đến đâu dùng đến đó để chả luôn nóng."}, {"thu_tu": 5, "noi_dung": "Làm dưa góp: đu đủ và cà rốt bào sợi ngâm nước muối loãng 10 phút, vớt ra bóp nhẹ với 1 thìa canh đường và 1 thìa canh giấm, để 15 phút cho giòn và thấm vị chua ngọt."}, {"thu_tu": 6, "noi_dung": "Pha nước chấm: hòa 300ml nước ấm với 3 thìa canh đường cho tan, thêm 4 thìa canh nước mắm và 2 thìa canh giấm, nêm lại theo tỉ lệ mặn - ngọt - chua cân bằng, vị đậm hơn nước chấm gỏi cuốn một chút. Cho tỏi băm và ớt thái lát vào sau cùng để nổi đẹp mặt."}, {"thu_tu": 7, "noi_dung": "Hoàn thiện: giữ nước chấm ấm (hâm lại nhẹ nếu nguội). Khi ăn, thả chả miếng, chả viên và dưa góp vào bát nước chấm, gắp bún và rau sống chấm cùng. Ăn ngay khi chả còn nóng là ngon nhất."}]'::jsonb WHERE slug = 'bun-cha-ha-noi';
UPDATE cong_thuc SET mo_ta = 'Bánh xèo miền Tây vỏ vàng ruộm, giòn rụm, thơm béo nước cốt dừa, nhân tôm thịt giá đỗ đầy đặn, cuốn rau sống chấm nước mắm chua ngọt. Công thức ghi rõ tỉ lệ pha bột, cách nghỉ bột và mẹo tráng chảo gang nóng già để bánh giòn lâu, không bị ỉu hay dính chảo.', nguyen_lieu = '[{"ten": "Bột gạo", "so_luong": 300, "don_vi": "g"}, {"ten": "Bột chiên giòn", "so_luong": 50, "don_vi": "g"}, {"ten": "Bột nghệ", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Nước cốt dừa", "so_luong": 200, "don_vi": "ml"}, {"ten": "Nước lọc", "so_luong": 400, "don_vi": "ml"}, {"ten": "Trứng gà", "so_luong": 1, "don_vi": "quả"}, {"ten": "Muối", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Hành lá thái nhỏ", "so_luong": 3, "don_vi": "cây"}, {"ten": "Thịt ba chỉ", "so_luong": 200, "don_vi": "g"}, {"ten": "Tôm sú nhỏ", "so_luong": 200, "don_vi": "g"}, {"ten": "Giá đỗ", "so_luong": 300, "don_vi": "g"}, {"ten": "Đậu xanh cà vỏ", "so_luong": 100, "don_vi": "g"}, {"ten": "Hành tây", "so_luong": 1, "don_vi": "củ"}, {"ten": "Dầu ăn", "so_luong": 6, "don_vi": "thìa canh"}, {"ten": "Nước mắm (pha nước chấm)", "so_luong": 3, "don_vi": "thìa canh"}, {"ten": "Đường (pha nước chấm)", "so_luong": 3, "don_vi": "thìa canh"}, {"ten": "Nước lọc (pha nước chấm)", "so_luong": 6, "don_vi": "thìa canh"}, {"ten": "Chanh", "so_luong": 1, "don_vi": "quả"}, {"ten": "Tỏi băm", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Ớt băm", "so_luong": 1, "don_vi": "quả"}, {"ten": "Rau sống (cải xanh, xà lách, rau thơm)", "so_luong": 400, "don_vi": "g"}, {"ten": "Dưa leo", "so_luong": 1, "don_vi": "quả"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Pha bột: trộn bột gạo, bột chiên giòn, bột nghệ và muối; cho nước cốt dừa và nước lọc vào từ từ, khuấy tan mịn không vón cục, thêm trứng đánh tan và hành lá. Để bột nghỉ 30 phút - 1 giờ cho bột nở đều, khi tráng bánh sẽ giòn và không bị nứt."}, {"thu_tu": 2, "noi_dung": "Sơ chế nhân: đậu xanh ngâm 2 giờ, hấp chín mềm. Thịt ba chỉ thái lát mỏng, ướp chút muối tiêu. Tôm rửa sạch, cắt bỏ râu, để nguyên vỏ cho ngọt và đẹp. Hành tây thái múi cau mỏng, giá đỗ rửa sạch để ráo."}, {"thu_tu": 3, "noi_dung": "Pha nước chấm: hòa đường với nước ấm cho tan, thêm nước mắm và nước cốt chanh, nêm vị chua ngọt nhẹ; cho tỏi ớt băm vào sau cùng."}, {"thu_tu": 4, "noi_dung": "Tráng bánh - bước quan trọng nhất: dùng chảo gang hoặc chảo chống dính đáy dày, đun lửa lớn cho chảo thật nóng, phết 1 thìa canh dầu ăn. Xào nhanh vài miếng thịt và tôm trong chảo cho săn, múc 1 vá bột (khoảng 80ml) đổ vào, nhanh tay nghiêng xoay chảo cho bột tráng thành lớp mỏng đều khắp mặt."}, {"thu_tu": 5, "noi_dung": "Cho nhân: rải đậu xanh, hành tây và giá đỗ lên một nửa bánh, đậy nắp 2 phút cho nhân chín bằng hơi. Mở nắp, hạ lửa vừa, rưới thêm 1 thìa cà phê dầu quanh rìa và rán tiếp 2-3 phút đến khi rìa bánh vàng giòn, nghe tiếng xèo xèo đều."}, {"thu_tu": 6, "noi_dung": "Gập bánh: dùng sạn gập đôi bánh, ép nhẹ rồi cho ra đĩa có lót giấy thấm dầu. Làm lần lượt đến hết bột, giữ chảo luôn nóng già trước mỗi cái bánh mới - chảo nguội là nguyên nhân chính khiến bánh bị dính và mềm."}, {"thu_tu": 7, "noi_dung": "Thưởng thức: cắt bánh thành miếng vừa ăn, cuốn với lá cải xanh hoặc xà lách cùng rau thơm và dưa leo, chấm nước mắm chua ngọt. Ăn ngay khi bánh còn nóng giòn; nếu cần giữ giòn trong lúc làm mẻ tiếp theo, để bánh trên vỉ trong lò ấm 100°C."}]'::jsonb WHERE slug = 'banh-xeo-mien-tay';
UPDATE cong_thuc SET mo_ta = 'Canh chua cá lóc miền Tây với vị chua dịu từ me và thơm, ngọt thanh, cá chắc thịt không tanh, rau bạc hà, đậu bắp giòn mát. Công thức hướng dẫn thứ tự cho nguyên liệu vào nồi và cách nêm chua - ngọt - mặn cân bằng để nồi canh trong, thơm mùi rau om ngò gai đúng kiểu sông nước.', nguyen_lieu = '[{"ten": "Cá lóc", "so_luong": 600, "don_vi": "g"}, {"ten": "Me vắt", "so_luong": 50, "don_vi": "g"}, {"ten": "Cà chua", "so_luong": 3, "don_vi": "quả"}, {"ten": "Thơm (dứa)", "so_luong": 0.5, "don_vi": "quả"}, {"ten": "Đậu bắp", "so_luong": 8, "don_vi": "quả"}, {"ten": "Bạc hà (dọc mùng)", "so_luong": 200, "don_vi": "g"}, {"ten": "Giá đỗ", "so_luong": 100, "don_vi": "g"}, {"ten": "Nước lọc", "so_luong": 1.5, "don_vi": "lít"}, {"ten": "Nước mắm", "so_luong": 3, "don_vi": "thìa canh"}, {"ten": "Đường", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Muối", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Tỏi băm", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Dầu ăn", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Rau om (rau ngổ)", "so_luong": 30, "don_vi": "g"}, {"ten": "Ngò gai", "so_luong": 20, "don_vi": "g"}, {"ten": "Ớt tươi", "so_luong": 2, "don_vi": "quả"}, {"ten": "Tiêu xay", "so_luong": 0.5, "don_vi": "thìa cà phê"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Sơ chế cá: cá lóc làm sạch, cắt khúc dày khoảng 3cm, chà muối và rửa lại cho hết nhớt. Ướp cá với 1 thìa canh nước mắm, chút tiêu và vài lát ớt trong 15 phút cho thấm và khử tanh."}, {"thu_tu": 2, "noi_dung": "Sơ chế rau: bạc hà tước bỏ vỏ xơ, cắt xéo khúc 4cm, ngâm nước muối loãng 10 phút rồi bóp nhẹ, rửa sạch, vắt ráo (bước này giúp bạc hà giòn và không bị ngứa). Đậu bắp cắt xéo, cà chua bổ múi cau, thơm cắt miếng vừa ăn, giá rửa sạch để ráo."}, {"thu_tu": 3, "noi_dung": "Lấy nước me: ngâm me vắt trong 200ml nước nóng 5 phút, dầm nát, lọc qua rây lấy nước cốt, bỏ hạt. Phi thơm tỏi băm với dầu ăn trong nồi, cho một nửa cà chua vào xào mềm để tạo màu và vị nền cho nước canh."}, {"thu_tu": 4, "noi_dung": "Nấu nước canh: đổ 1,5 lít nước vào nồi, đun sôi thì cho nước cốt me và thơm vào, nấu 5 phút cho vị chua thơm lan đều. Nêm 2 thìa canh nước mắm, 2 thìa canh đường và muối, nếm thử: vị đúng là chua nhẹ đầu lưỡi, ngọt thanh, mặn vừa."}, {"thu_tu": 5, "noi_dung": "Cho cá vào nấu: nước sôi trở lại thì nhẹ nhàng thả từng khúc cá vào, nấu lửa vừa 7-8 phút đến khi cá chín trắng. Không khuấy đảo mạnh và không đậy nắp kín để cá không nát và nước canh không bị tanh; hớt bọt nếu có."}, {"thu_tu": 6, "noi_dung": "Cho rau theo thứ tự: đậu bắp và bạc hà vào trước nấu 2 phút, tiếp đến cà chua còn lại và giá đỗ, đảo nhẹ một lần rồi tắt bếp ngay để rau giữ độ giòn và màu xanh. Nêm lại nước mắm lần cuối cho vừa ăn."}, {"thu_tu": 7, "noi_dung": "Hoàn thiện: múc canh ra tô, rắc rau om, ngò gai thái nhỏ, vài lát ớt và một ít tỏi phi lên mặt. Ăn nóng với cơm trắng và chén nước mắm ớt chấm cá là chuẩn vị miền Tây."}]'::jsonb WHERE slug = 'canh-chua-ca-loc';
UPDATE cong_thuc SET mo_ta = 'Gỏi cuốn tôm thịt tươi mát, cuốn chắc tay, nhìn xuyên qua lớp bánh tráng thấy tôm đỏ thịt trắng đẹp mắt, chấm tương đen đậu phộng béo thơm. Công thức hướng dẫn cách luộc thịt ngọt, nhúng bánh tráng đúng độ và kỹ thuật cuốn chặt không rách, kèm cách pha tương chấm sánh mịn như ngoài quán.', nguyen_lieu = '[{"ten": "Bánh tráng (đường kính 22cm)", "so_luong": 12, "don_vi": "cái"}, {"ten": "Thịt ba chỉ", "so_luong": 300, "don_vi": "g"}, {"ten": "Tôm sú", "so_luong": 300, "don_vi": "g"}, {"ten": "Bún tươi sợi nhỏ", "so_luong": 300, "don_vi": "g"}, {"ten": "Xà lách", "so_luong": 200, "don_vi": "g"}, {"ten": "Lá hẹ", "so_luong": 50, "don_vi": "g"}, {"ten": "Rau thơm (húng quế, tía tô)", "so_luong": 50, "don_vi": "g"}, {"ten": "Dưa leo", "so_luong": 1, "don_vi": "quả"}, {"ten": "Giá đỗ", "so_luong": 100, "don_vi": "g"}, {"ten": "Hành tím (luộc thịt)", "so_luong": 2, "don_vi": "củ"}, {"ten": "Gừng (luộc thịt)", "so_luong": 20, "don_vi": "g"}, {"ten": "Tương đen (hoisin)", "so_luong": 4, "don_vi": "thìa canh"}, {"ten": "Bơ đậu phộng", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Nước luộc thịt", "so_luong": 100, "don_vi": "ml"}, {"ten": "Đường (pha tương)", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Tỏi băm", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Đậu phộng rang giã dập", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Ớt băm", "so_luong": 1, "don_vi": "quả"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Luộc thịt: cho ba chỉ vào nồi nước lạnh cùng hành tím đập dập, gừng và 1 thìa cà phê muối, đun sôi rồi hạ lửa nhỏ luộc 15-18 phút đến khi thịt chín (xiên đũa vào không ra nước hồng). Vớt thịt ngâm nước lạnh 5 phút cho săn, thái lát mỏng 2-3mm. Giữ lại nước luộc để pha tương."}, {"thu_tu": 2, "noi_dung": "Luộc tôm: dùng chính nồi nước luộc thịt đang sôi, cho tôm vào luộc 2-3 phút đến khi tôm cong và đỏ đều thì vớt ra ngâm nước đá cho giòn. Bóc vỏ, bỏ chỉ đen, chẻ đôi theo chiều dọc để khi cuốn lộ mặt đỏ đẹp."}, {"thu_tu": 3, "noi_dung": "Chuẩn bị phần còn lại: bún chần nhanh qua nước sôi rồi xả lạnh, để ráo. Rau sống rửa sạch, vẩy thật ráo nước (rau ướt làm bánh tráng nhũn và cuốn bị trơn). Dưa leo cắt thanh dài, hẹ rửa sạch để nguyên cọng."}, {"thu_tu": 4, "noi_dung": "Pha tương chấm: phi thơm tỏi băm với chút dầu, cho tương đen, bơ đậu phộng, 100ml nước luộc thịt và đường vào khuấy đều, đun lửa nhỏ 2-3 phút đến khi tương sánh mịn. Múc ra chén, rắc đậu phộng rang và ớt băm lên mặt."}, {"thu_tu": 5, "noi_dung": "Nhúng bánh tráng: dùng đĩa nông đựng nước ấm, nhúng nhanh từng cái bánh tráng 2-3 giây rồi đặt lên thớt sạch. Bánh còn hơi cứng khi mới nhúng là vừa, bánh sẽ tự mềm trong lúc xếp nhân; nhúng lâu quá bánh nhũn và rách khi cuốn."}, {"thu_tu": 6, "noi_dung": "Cuốn gỏi: đặt lá xà lách, rau thơm, ít bún, giá và dưa leo ở phần dưới bánh; gập hai mép bên vào, cuốn lên một vòng cho chặt rồi đặt 2 miếng thịt và 2 nửa con tôm (mặt đỏ úp xuống bánh để nhìn xuyên qua đẹp), thêm cọng hẹ thò ra ngoài một đầu, cuốn tiếp đến hết bánh. Cuốn chắc tay nhưng không kéo căng làm rách bánh."}, {"thu_tu": 7, "noi_dung": "Hoàn thiện: xếp gỏi cuốn lên đĩa, để các cuốn không chạm nhau để khỏi dính. Ăn ngay trong 30 phút sau khi cuốn, chấm ngập trong tương đậu phộng. Nếu chưa ăn liền, phủ khăn ẩm lên trên và để nơi mát tối đa 1 giờ."}]'::jsonb WHERE slug = 'goi-cuon-tom-thit';
UPDATE cong_thuc SET mo_ta = 'Cơm chiên Dương Châu hạt cơm tơi rời, vàng óng, quyện trứng, tôm, lạp xưởng và xá xíu thơm mùi chảo lửa lớn. Công thức chỉ rõ cách chọn và làm khô cơm, thứ tự cho nguyên liệu vào chảo và cách nêm nếm để bạn chiên được đĩa cơm chuẩn vị nhà hàng Hoa ngay tại bếp nhà.', nguyen_lieu = '[{"ten": "Cơm trắng để nguội (nấu từ gạo khô)", "so_luong": 3, "don_vi": "chén"}, {"ten": "Trứng gà", "so_luong": 3, "don_vi": "quả"}, {"ten": "Tôm tươi bóc vỏ", "so_luong": 120, "don_vi": "g"}, {"ten": "Thịt xá xíu (hoặc thịt heo quay)", "so_luong": 100, "don_vi": "g"}, {"ten": "Lạp xưởng", "so_luong": 1, "don_vi": "cây"}, {"ten": "Đậu Hà Lan và cà rốt hạt lựu", "so_luong": 100, "don_vi": "g"}, {"ten": "Tỏi băm", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Hành lá thái nhỏ", "so_luong": 3, "don_vi": "cây"}, {"ten": "Nước tương", "so_luong": 1.5, "don_vi": "thìa canh"}, {"ten": "Dầu hào", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Đường", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Muối", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Tiêu xay", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Dầu ăn", "so_luong": 3, "don_vi": "thìa canh"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Chuẩn bị cơm - yếu tố quyết định: dùng cơm nấu từ gạo khô, ít nước, để nguội và cho vào tủ lạnh ít nhất 4 giờ (tốt nhất qua đêm) cho hạt cơm khô mặt, tơi rời. Trước khi chiên, dùng tay bóp nhẹ cho cơm hết vón cục. Cơm nóng hoặc cơm nhão là nguyên nhân khiến cơm chiên bị bết."}, {"thu_tu": 2, "noi_dung": "Sơ chế nguyên liệu: tôm rửa sạch, thấm khô, cắt hạt lựu, ướp chút muối tiêu. Xá xíu cắt hạt lựu 1cm. Lạp xưởng chần nước sôi 2 phút, thái hạt lựu. Trứng đánh tan với một nhúm muối. Đậu Hà Lan và cà rốt chần sơ 1 phút, để ráo."}, {"thu_tu": 3, "noi_dung": "Chiên trứng riêng: đun chảo thật nóng với 1 thìa canh dầu, đổ trứng vào đảo nhanh tay cho trứng vừa chín tới, còn mềm xốp thì trút ra đĩa. Chiên riêng giúp trứng không bị nát vụn và tanh khi trộn vào cơm sau."}, {"thu_tu": 4, "noi_dung": "Xào phần nhân: cho tiếp 1 thìa canh dầu, phi thơm tỏi, cho lạp xưởng vào đảo cho tươm mỡ thơm, thêm tôm và xá xíu xào lửa lớn 2 phút đến khi tôm chuyển hồng. Trút ra cùng đĩa trứng."}, {"thu_tu": 5, "noi_dung": "Chiên cơm: cho thìa dầu còn lại, chảo phải thật nóng và bốc khói nhẹ. Cho cơm vào, dàn đều, để yên 20-30 giây cho mặt dưới hơi xém rồi mới đảo. Đảo và ấn nhẹ liên tục 3-4 phút trên lửa lớn nhất đến khi hạt cơm khô, tơi, nghe tiếng lách tách."}, {"thu_tu": 6, "noi_dung": "Nêm và trộn: rưới nước tương quanh thành chảo (để nước tương gặp nhiệt bốc thơm) chứ không đổ trực tiếp lên cơm, thêm dầu hào, đường, muối, đảo đều. Cho lại trứng, tôm, xá xíu, lạp xưởng và đậu cà rốt vào, đảo thêm 1-2 phút cho hòa quyện, nếm lại vị mặn nhẹ, thơm, hậu ngọt."}, {"thu_tu": 7, "noi_dung": "Hoàn thiện: tắt bếp, cho hành lá và tiêu xay, đảo một vòng rồi múc ra đĩa. Cơm chiên ngon khi hạt cơm bóng nhẹ, tơi từng hạt, ăn kèm dưa leo, cà chua và chén nước tương ớt."}]'::jsonb WHERE slug = 'com-chien-duong-chau';
UPDATE cong_thuc SET mo_ta = 'Đậu hũ sốt cà chua dân dã mà đưa cơm: đậu chiên vàng giòn nhẹ bên ngoài, mềm mịn bên trong, ôm trọn sốt cà chua chua ngọt sánh mượt. Món chay - mặn đều dùng được này có công thức đơn giản nhưng ghi rõ mẹo chiên đậu không nát, không bắn dầu và cách nấu sốt cà chua đỏ đẹp, dậy vị.', nguyen_lieu = '[{"ten": "Đậu hũ trắng (loại chắc)", "so_luong": 4, "don_vi": "bìa"}, {"ten": "Cà chua chín đỏ", "so_luong": 4, "don_vi": "quả"}, {"ten": "Hành tím băm", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Tỏi băm", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Nước mắm (hoặc nước tương nếu ăn chay)", "so_luong": 1.5, "don_vi": "thìa canh"}, {"ten": "Đường", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Tương cà", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Nước lọc", "so_luong": 100, "don_vi": "ml"}, {"ten": "Dầu ăn", "so_luong": 5, "don_vi": "thìa canh"}, {"ten": "Hành lá", "so_luong": 3, "don_vi": "cây"}, {"ten": "Ngò rí", "so_luong": 20, "don_vi": "g"}, {"ten": "Tiêu xay", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Ớt tươi (tùy thích)", "so_luong": 1, "don_vi": "quả"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Sơ chế đậu: đậu hũ rửa nhẹ, để ráo rồi dùng khăn sạch hoặc giấy bếp thấm thật khô bề mặt - đậu khô thì chiên mới vàng giòn và không bắn dầu. Cắt mỗi bìa thành 4 miếng vuông vừa ăn, rắc một lớp muối thật mỏng lên mặt đậu."}, {"thu_tu": 2, "noi_dung": "Sơ chế cà chua: cà chua rửa sạch, bổ múi cau rồi cắt hạt lựu nhỏ (hoặc chần nước sôi, bóc vỏ, băm nhuyễn nếu muốn sốt mịn). Cà càng chín đỏ, sốt càng đẹp màu và ngọt tự nhiên."}, {"thu_tu": 3, "noi_dung": "Chiên đậu: đun dầu trong chảo đến khi nóng già (thử bằng đầu đũa thấy sủi tăm mạnh), nhẹ nhàng thả đậu vào, chiên lửa vừa. Đợi mặt dưới vàng cứng mới lật để đậu không nát; chiên đến khi các mặt vàng đều thì vớt ra để ráo dầu."}, {"thu_tu": 4, "noi_dung": "Nấu sốt cà chua: chừa lại khoảng 1 thìa canh dầu trong chảo, phi thơm hành tím và tỏi. Cho cà chua vào xào lửa vừa 5-7 phút, dầm nhẹ cho cà mềm nhừ và ra màu đỏ, thêm tương cà, nước lọc, đường và nước mắm, đun nhỏ lửa đến khi sốt sánh lại, vị chua - ngọt - mặn hài hòa."}, {"thu_tu": 5, "noi_dung": "Om đậu với sốt: cho đậu đã chiên vào chảo sốt, đảo thật nhẹ tay hoặc lắc chảo cho sốt phủ đều, om lửa nhỏ 3-4 phút để đậu thấm vị mà vẫn giữ được lớp vỏ giòn nhẹ."}, {"thu_tu": 6, "noi_dung": "Hoàn thiện: rắc hành lá thái nhỏ, ngò rí, tiêu và vài lát ớt lên trên, tắt bếp. Ăn nóng với cơm trắng; phần sốt cà chua chan cơm rất bắt vị. Nếu ăn chay thuần, thay nước mắm bằng nước tương và thêm chút đường cho tròn vị."}]'::jsonb WHERE slug = 'dau-hu-sot-ca-chua';
UPDATE cong_thuc SET mo_ta = 'Bánh flan caramel mềm mịn như lụa, thơm mùi sữa và vani, phủ lớp caramel nâu hổ phách hơi đắng nhẹ cân bằng vị ngọt. Công thức hướng dẫn cách thắng caramel không cháy khét, lọc hỗn hợp trứng sữa đúng cách và hấp cách thủy lửa nhỏ để flan không bị rỗ, không tanh mùi trứng.', nguyen_lieu = '[{"ten": "Đường (làm caramel)", "so_luong": 80, "don_vi": "g"}, {"ten": "Nước (làm caramel)", "so_luong": 40, "don_vi": "ml"}, {"ten": "Trứng gà nguyên quả", "so_luong": 4, "don_vi": "quả"}, {"ten": "Lòng đỏ trứng gà", "so_luong": 2, "don_vi": "cái"}, {"ten": "Sữa tươi không đường", "so_luong": 500, "don_vi": "ml"}, {"ten": "Sữa đặc có đường", "so_luong": 100, "don_vi": "ml"}, {"ten": "Đường (làm flan)", "so_luong": 40, "don_vi": "g"}, {"ten": "Tinh chất vani", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Muối", "so_luong": 1, "don_vi": "nhúm"}, {"ten": "Nước cốt chanh", "so_luong": 0.5, "don_vi": "thìa cà phê"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Thắng caramel: cho 80g đường và 40ml nước vào nồi nhỏ, đun lửa vừa, không khuấy (chỉ lắc nhẹ nồi) đến khi đường tan và chuyển màu nâu hổ phách. Nhỏ nước cốt chanh vào ngay từ đầu giúp caramel không bị lại đường. Khi vừa đạt màu, tắt bếp, thêm 1 thìa canh nước nóng khuấy đều rồi nhanh tay tráng một lớp mỏng vào đáy 6 khuôn flan. Để muộn vài giây caramel sẽ cháy đắng."}, {"thu_tu": 2, "noi_dung": "Pha hỗn hợp trứng: đánh tan nhẹ trứng nguyên quả và lòng đỏ với 40g đường bằng phới lồng, chỉ khuấy một chiều cho tan, tránh đánh bông tạo bọt - đây là nguyên nhân chính làm flan bị rỗ."}, {"thu_tu": 3, "noi_dung": "Pha sữa: đun sữa tươi và sữa đặc đến khoảng 60-70°C (ấm nóng, bốc hơi nhẹ, chưa sôi). Đổ sữa ấm từ từ vào trứng, vừa đổ vừa khuấy đều, thêm vani và một nhúm muối. Đổ sữa đang sôi vào sẽ làm trứng chín lợn cợn."}, {"thu_tu": 4, "noi_dung": "Lọc hỗn hợp: lọc qua rây mịn 2 lần để loại bỏ lợn cợn và bọt, giúp mặt flan láng mịn. Hớt sạch bọt trên bề mặt nếu còn, rồi rót vào các khuôn đã có caramel."}, {"thu_tu": 5, "noi_dung": "Hấp cách thủy: đậy nắp hoặc bọc giấy bạc từng khuôn, xếp vào nồi hấp khi nước đã sôi, hạ lửa nhỏ nhất sao cho nước chỉ sôi lăn tăn nhẹ. Hấp 30-35 phút; cứ 10 phút mở nắp lau hơi nước một lần để nước không nhỏ xuống mặt bánh. Nếu dùng lò nướng: nướng cách thủy 150°C trong 40-45 phút."}, {"thu_tu": 6, "noi_dung": "Kiểm tra độ chín: lắc nhẹ khuôn, mặt flan rung nhẹ như thạch nhưng không lỏng nước là chín; xiên tăm vào thấy tăm sạch. Để nguội hoàn toàn rồi cho vào tủ lạnh ít nhất 4 giờ (ngon nhất qua đêm) cho flan săn và thấm caramel."}, {"thu_tu": 7, "noi_dung": "Lấy bánh và thưởng thức: dùng dao mỏng lách quanh thành khuôn, úp ngược ra đĩa, lớp caramel sẽ chảy phủ mặt bánh đẹp mắt. Flan đạt chuẩn khi cắt ra thấy mặt cắt mịn, không lỗ khí, vị béo thơm, ngọt vừa và thơm vani dịu."}]'::jsonb WHERE slug = 'banh-flan-caramel';
UPDATE cong_thuc SET mo_ta = 'Gà nướng mật ong da vàng óng, bóng đẹp, thơm mùi tỏi sả, thịt mềm ngọt thấm vị từ trong ra ngoài. Công thức ghi rõ tỉ lệ nước ướp chuẩn, thời gian ướp tối thiểu và cách nướng hai giai đoạn với lần phết mật ong cuối để da lên màu cánh gián mà không bị cháy khét vị đắng.', nguyen_lieu = '[{"ten": "Gà ta nguyên con (khoảng 1,4kg) hoặc đùi gà", "so_luong": 1.4, "don_vi": "kg"}, {"ten": "Mật ong", "so_luong": 3, "don_vi": "thìa canh"}, {"ten": "Nước mắm", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Nước tương", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Dầu hào", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Đường", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Tỏi băm", "so_luong": 1.5, "don_vi": "thìa canh"}, {"ten": "Hành tím băm", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Sả băm", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Bột ngũ vị hương", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Tiêu xay", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Dầu ăn (hoặc dầu mè)", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Muối", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Chanh", "so_luong": 1, "don_vi": "quả"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Sơ chế gà: chà xát gà với muối và nước cốt chanh (hoặc gừng đập dập) 5 phút để khử mùi, rửa sạch, để thật ráo hoặc thấm khô bằng khăn. Xẻ nhẹ vài đường trên phần thịt dày như ức và đùi để gia vị thấm sâu và thịt chín đều. Gà càng khô mặt, da nướng càng đẹp."}, {"thu_tu": 2, "noi_dung": "Pha nước ướp: trộn đều 2 thìa canh mật ong (giữ lại 1 thìa để phết sau), nước mắm, nước tương, dầu hào, đường, tỏi, hành tím, sả băm, ngũ vị hương, tiêu và dầu ăn thành hỗn hợp sệt thơm."}, {"thu_tu": 3, "noi_dung": "Ướp gà: xoa đều nước ướp khắp trong ngoài con gà, mát-xa nhẹ 2-3 phút, cho vào hộp kín ướp ngăn mát tối thiểu 2 giờ, ngon nhất 6-8 giờ hoặc qua đêm. Trước khi nướng 30 phút, lấy gà ra để về nhiệt độ phòng cho chín đều."}, {"thu_tu": 4, "noi_dung": "Nướng giai đoạn 1: làm nóng lò 200°C trước 10 phút. Đặt gà lên vỉ nướng có khay hứng mỡ bên dưới (lót giấy bạc), nướng 25 phút. Nếu nướng than, để than hồng đều, gà cách than 15cm và trở đều tay. Nếu dùng nồi chiên không dầu, chia gà thành 2 đùi lớn, nướng 180°C trong 20 phút đầu."}, {"thu_tu": 5, "noi_dung": "Phết mật ong và nướng giai đoạn 2: lấy gà ra, phết lớp mật ong còn lại pha với 1 thìa cà phê nước ướp đun sôi. Nướng tiếp 10-15 phút ở 190°C đến khi da vàng nâu bóng, hơi xém cạnh nhẹ. Chỉ phết mật ong ở giai đoạn cuối vì mật ong rất dễ cháy nếu nướng lâu từ đầu."}, {"thu_tu": 6, "noi_dung": "Kiểm tra và nghỉ thịt: gà chín khi xiên vào phần đùi dày nhất thấy nước chảy ra trong, không hồng; nhiệt độ trong thịt đạt 75°C nếu có nhiệt kế. Để gà nghỉ 10 phút trước khi chặt để nước thịt phân bổ lại, thịt mềm và mọng hơn."}, {"thu_tu": 7, "noi_dung": "Thưởng thức: chặt gà miếng vừa ăn, bày lên đĩa với rau răm, dưa leo; chấm muối tiêu chanh hoặc nước mắm gừng. Phần nước thịt trong khay rưới lại lên gà cho bóng đẹp và đậm vị."}]'::jsonb WHERE slug = 'ga-nuong-mat-ong';
UPDATE cong_thuc SET mo_ta = 'Mì Ý sốt bò bằm (spaghetti Bolognese) với sốt cà chua nấu chậm đậm đà, thịt bò thơm mùi tỏi và lá oregano, sợi mì dai vừa chín tới. Công thức hướng dẫn cách luộc mì đúng chuẩn al dente, giữ lại nước luộc mì để sốt sánh mượt và trình bày đĩa mì như nhà hàng Ý tại nhà.', nguyen_lieu = '[{"ten": "Mì spaghetti", "so_luong": 200, "don_vi": "g"}, {"ten": "Thịt bò xay (có chút mỡ)", "so_luong": 300, "don_vi": "g"}, {"ten": "Cà chua chín", "so_luong": 3, "don_vi": "quả"}, {"ten": "Sốt cà chua (tomato paste)", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Hành tây", "so_luong": 1, "don_vi": "củ"}, {"ten": "Cà rốt", "so_luong": 0.5, "don_vi": "củ"}, {"ten": "Tỏi băm", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Dầu ô liu (hoặc dầu ăn)", "so_luong": 2, "don_vi": "thìa canh"}, {"ten": "Lá oregano khô", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Lá húng quế tươi (basil)", "so_luong": 20, "don_vi": "g"}, {"ten": "Đường", "so_luong": 1, "don_vi": "thìa cà phê"}, {"ten": "Muối", "so_luong": 1, "don_vi": "thìa canh"}, {"ten": "Tiêu xay", "so_luong": 0.5, "don_vi": "thìa cà phê"}, {"ten": "Phô mai Parmesan bào", "so_luong": 30, "don_vi": "g"}, {"ten": "Bơ lạt", "so_luong": 15, "don_vi": "g"}]'::jsonb, cac_buoc = '[{"thu_tu": 1, "noi_dung": "Sơ chế: hành tây và cà rốt cắt hạt lựu nhỏ; cà chua chần nước sôi 1 phút, bóc vỏ, bỏ hạt, băm nhuyễn (hoặc dùng cà chua hộp xay sẵn). Thịt bò xay để ra khỏi tủ lạnh 15 phút, ướp nhẹ muối tiêu."}, {"thu_tu": 2, "noi_dung": "Xào thịt bò: đun nóng dầu ô liu trong nồi đáy dày, cho thịt bò vào dàn mỏng, để yên 2 phút cho mặt dưới xém vàng rồi mới đảo và dằm tơi. Mặt xém nhẹ tạo vị thơm đậm cho sốt. Vớt thịt ra, giữ lại phần nước mỡ trong nồi."}, {"thu_tu": 3, "noi_dung": "Nấu nền sốt: dùng chính nồi đó, cho hành tây và cà rốt vào xào lửa vừa 5 phút đến mềm và ngọt, thêm tỏi băm và sốt cà chua (tomato paste) đảo 1-2 phút đến khi paste sậm màu và thơm."}, {"thu_tu": 4, "noi_dung": "Nấu chậm sốt: cho cà chua băm và thịt bò trở lại nồi, thêm 200ml nước, oregano, đường, muối, tiêu. Đun sôi rồi hạ lửa nhỏ, nấu liu riu 25-30 phút, thỉnh thoảng khuấy, đến khi sốt sánh lại và bóng mỡ nhẹ. Nấu chậm là bí quyết để sốt Bolognese đậm đà, hết vị chua gắt của cà chua sống."}, {"thu_tu": 5, "noi_dung": "Luộc mì al dente: đun nồi nước lớn thật sôi, cho 1 thìa canh muối (nước luộc mặn như nước biển loãng). Cho mì vào luộc theo thời gian trên bao bì trừ đi 1 phút, khuấy vài lần đầu để mì không dính. Trước khi đổ mì, múc giữ lại 1 chén nước luộc mì - tinh bột trong nước này giúp sốt bám mì sánh mượt."}, {"thu_tu": 6, "noi_dung": "Trộn mì với sốt: cho mì vừa vớt (không xả nước lạnh) thẳng vào nồi sốt cùng bơ lạt và 3-4 thìa canh nước luộc mì, đảo đều trên lửa vừa 1-2 phút để sợi mì thấm sốt và chín tới độ dai nhẹ al dente. Thêm nước luộc mì nếu sốt quá đặc."}, {"thu_tu": 7, "noi_dung": "Trình bày: gắp mì xoắn thành tổ cao trong đĩa sâu, múc thêm sốt bò lên trên, rắc phô mai Parmesan bào và vài lá húng quế tươi, thêm chút tiêu xay. Ăn ngay khi còn nóng kèm bánh mì bơ tỏi nếu thích."}]'::jsonb WHERE slug = 'mi-y-sot-bo-bam';

-- ---------------------------------------------------------------------------
-- 2) KHÓA HỌC (5 khóa)
-- ---------------------------------------------------------------------------
UPDATE khoa_hoc SET mo_ta = 'Khóa nền tảng cho người chưa từng vào bếp: từ sắp xếp căn bếp an toàn, cầm dao cắt thái, ướp gia vị cho đến tự tay nấu trọn một bữa cơm ngon. Bài học ngắn gọn, dễ làm theo, thực hành ngay với nguyên liệu quen thuộc hằng ngày.', mo_ta_chi_tiet = 'Bạn có muốn tự nấu ăn nhưng chưa biết bắt đầu từ đâu? Khóa học này dẫn bạn đi từng bước nhỏ, chắc chắn: làm quen và sắp xếp căn bếp an toàn, nhận biết các dụng cụ thật sự cần thiết, học kỹ thuật sơ chế - cắt thái - ướp gia vị nền tảng, rồi thực hành ngay ba món đầu tay trong một bữa cơm hoàn chỉnh.

Mỗi bài gồm video hướng dẫn chi tiết và bài tập trắc nghiệm ngắn để củng cố kiến thức. Học xong khóa, bạn sẽ tự tin lên thực đơn, đi chợ đúng nguyên liệu và nấu được bữa cơm gia đình gọn gàng, ngon miệng mà không còn lúng túng trước bếp.', co_bai_tap = true WHERE id = 'cd5ce0af-ebdb-45cb-85b1-b19eac4c0a76';
UPDATE khoa_hoc SET mo_ta = 'Giải mã bí quyết của tô phở chuẩn vị: nước dùng trong veo ninh từ xương bò, gia vị nướng rang đúng cách, sợi phở trụng vừa tới và thịt bò thái mỏng ngang thớ. Học xong, bạn tự tin nấu phở và các món bún nước ngon như ngoài quán.', mo_ta_chi_tiet = 'Phở ngon hay dở quyết định bởi nồi nước dùng. Khóa học này tập trung vào ba trụ cột của phở chuẩn vị Hà Nội: ninh nước dùng trong, thơm và ngọt thanh từ xương; xử lý bánh phở và thịt bò đúng kỹ thuật; xếp tô và nêm nếm lần cuối như một quán phở lâu năm.

Bạn cũng sẽ nắm được nguyên tắc chung để biến tấu sang các món bún nước khác như bún thang, bún mọc hay bún riêu. Mỗi bài học đều có bài tập trắc nghiệm giúp bạn ghi nhớ các điểm mấu chốt về thời gian ninh, thứ tự cho gia vị và cách trụng bánh.', co_bai_tap = true WHERE id = 'd7b34f2b-f026-446e-900d-f80677ff0d1b';
UPDATE khoa_hoc SET mo_ta = 'Nhập môn làm bánh Âu từ con số 0: hiểu nguyên liệu và dụng cụ, trộn bột - đánh trứng - kiểm soát lò nướng đúng kỹ thuật, và hoàn thành chiếc bánh bông lan đầu tay mềm xốp, thơm bơ sữa ngay trong bếp nhà bạn.', mo_ta_chi_tiet = 'Làm bánh không khó nếu bạn hiểu đúng nguyên lý. Khóa học bắt đầu từ cách đọc một công thức bánh, phân biệt các loại bột, chất tạo nở và vai trò của trứng, bơ, đường; tiếp theo là các kỹ thuật cốt lõi: đánh bông trứng, trộn bột kiểu fold giữ bọt khí, và kiểm soát nhiệt độ lò - nguyên nhân của hầu hết các mẻ bánh hỏng.

Bài cuối là thực hành hoàn chỉnh một chiếc bánh bông lan cơ bản kèm trang trí đơn giản, giúp bạn có nền tảng vững để tiến tới bánh quy, bánh mì và các dòng bánh Âu khác.', co_bai_tap = true WHERE id = 'ccedd63c-ce0e-43a8-9ef3-a7f093d7bf5c';
UPDATE khoa_hoc SET mo_ta = 'Nấu món chay thanh đạm mà vẫn đậm đà và đủ chất: nguồn đạm thực vật phong phú, gia vị chay tạo vị ngọt tự nhiên, kỹ thuật kho - xào - nấu canh chuẩn và cách lên mâm cơm chay cân bằng dinh dưỡng cho cả gia đình.', mo_ta_chi_tiet = 'Ăn chay ngon không có nghĩa là nhạt nhẽo hay thiếu chất. Khóa học hướng dẫn bạn xây dựng khẩu phần chay đủ đạm từ đậu hũ, các loại đậu và nấm; tạo vị umami tự nhiên từ nấm hương, rong biển và rau củ nướng; cùng các kỹ thuật kho, xào, nấu canh giúp món chay đậm đà như món mặn.

Bài cuối hướng dẫn lên thực đơn và nấu trọn một mâm cơm chay hài hòa về màu sắc, hương vị và dinh dưỡng - phù hợp cho ngày rằm, tháng ăn chay hoặc đơn giản là đổi vị thanh nhẹ cho gia đình.', co_bai_tap = true WHERE id = '7ba8fda5-2e89-4b4c-bcf8-54b89403f06a';
UPDATE khoa_hoc SET mo_ta = 'Nâng tầm tay nghề với kỹ thuật của bếp nhà hàng: dùng dao như đầu bếp chuyên nghiệp, kiểm soát nhiệt và thời điểm hoàn hảo, tổ chức mise en place và ra món đúng chuẩn. Dành cho người đã vững cơ bản và muốn bứt phá rõ rệt.', mo_ta_chi_tiet = 'Điều làm nên đẳng cấp đầu bếp không nằm ở công thức bí mật, mà ở kỹ thuật nền: con dao bén và đôi tay chuẩn xác, khả năng đọc nhiệt độ chảo bằng mắt và tai, và thói quen mise en place - mọi thứ sẵn sàng đúng vị trí trước khi bắt lửa.

Khóa học hệ thống ba kỹ năng này qua bài giảng chi tiết và bài tập tình huống, kèm các tiêu chuẩn ra món của bếp nhà hàng: nêm nếm xuyên suốt quá trình, giữ nóng đúng cách và trình bày đĩa ăn có chủ đích. Hoàn thành khóa, cách bạn nấu ăn sẽ thay đổi rõ rệt ở tốc độ, sự ổn định và chất lượng món ăn.', co_bai_tap = true WHERE id = '372f120f-ebeb-444e-8a4a-dc73f702d27e';

-- ---------------------------------------------------------------------------
-- 3) BÀI HỌC (15 bài, kèm 45 câu trắc nghiệm)
-- ---------------------------------------------------------------------------
UPDATE bai_hoc SET tieu_de = 'Làm quen căn bếp: dụng cụ thiết yếu và an toàn khi nấu ăn', mo_ta = 'Bài mở đầu giúp bạn sắp xếp căn bếp gọn gàng và an toàn trước khi nấu món đầu tiên. Bạn sẽ biết những dụng cụ thật sự cần thiết gồm dao, thớt, chảo và nồi, cách chọn mua vừa đủ dùng mà không lãng phí. Bài học nhấn mạnh nguyên tắc dùng thớt riêng cho thực phẩm sống và chín để tránh nhiễm chéo, cách cầm dao và đặt tay an toàn, cùng thói quen vệ sinh tay, bề mặt bếp và bảo quản thực phẩm đúng cách. Đây là nền tảng giúp mọi buổi nấu ăn sau này nhẹ nhàng và tự tin hơn.', bai_tap = '[{"cau_hoi": "Vì sao cần dùng thớt riêng cho thực phẩm sống và thực phẩm chín?", "lua_chon": ["Để thớt bền và đẹp lâu hơn", "Tránh nhiễm chéo vi khuẩn từ đồ sống sang đồ chín", "Để cắt thái nhanh hơn", "Để thớt dễ rửa hơn"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Tư thế tay an toàn khi cầm giữ nguyên liệu để cắt là gì?", "lua_chon": ["Duỗi thẳng các ngón tay trên nguyên liệu", "Đặt ngón cái lên lưỡi dao để giữ", "Cuộn các đầu ngón tay vào trong như hình móng vuốt", "Nắm nguyên liệu thật chặt bằng cả bàn tay"], "dap_an_dung": 2, "diem": 10}, {"cau_hoi": "Thực phẩm đã nấu chín nên được bảo quản trong tủ lạnh tối đa khoảng bao lâu?", "lua_chon": ["Khoảng 3-4 ngày", "Khoảng 2 tuần", "Khoảng 1 tháng", "Không cần bảo quản tủ lạnh"], "dap_an_dung": 0, "diem": 10}]'::jsonb WHERE id = '3262a323-39fc-4a20-9ed5-7c082df69a96';
UPDATE bai_hoc SET tieu_de = 'Kỹ thuật sơ chế cơ bản: rửa, cắt thái và ướp gia vị', mo_ta = 'Bài học tập trung vào khâu sơ chế - bước quyết định món ăn có ngon và việc nấu có nhanh hay không. Bạn sẽ học cách rửa rau và thịt đúng cách, các kiểu cắt thái cơ bản như hạt lựu, sợi, lát mỏng và múi cau, cùng nguyên tắc cắt đều tay để nguyên liệu chín cùng một lúc. Phần ướp gia vị hướng dẫn tỉ lệ mặn - ngọt - thơm nền tảng, thứ tự cho gia vị và thời gian ướp phù hợp với từng loại thịt, cá và hải sản để món nào cũng thấm vị từ trong ra ngoài.', bai_tap = '[{"cau_hoi": "Vì sao nên cắt nguyên liệu thành miếng đều nhau?", "lua_chon": ["Để món ăn trông sang hơn", "Để các miếng chín đều cùng một thời điểm", "Để tiết kiệm dao thớt", "Để rửa nhanh hơn"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Khi ướp thịt, thứ tự cho gia vị nào sau đây hợp lý nhất?", "lua_chon": ["Cho dầu ăn trước rồi mới cho gia vị mặn", "Cho gia vị mặn và thơm trước, dầu ăn cho sau cùng để khóa vị", "Cho đường thật nhiều ngay từ đầu", "Chỉ ướp muối, không cần gia vị thơm"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Cá và hải sản thường chỉ nên ướp trong bao lâu?", "lua_chon": ["Càng lâu càng tốt, nên ướp qua đêm", "Khoảng 2-3 giờ", "Khoảng 15-20 phút là vừa", "Không bao giờ cần ướp"], "dap_an_dung": 2, "diem": 10}]'::jsonb WHERE id = '8097086e-8d88-42c9-81a4-8e744d687545';
UPDATE bai_hoc SET tieu_de = 'Thực hành món đầu tay: trứng chiên, rau xào tỏi và canh rau củ', mo_ta = 'Bài thực hành tổng hợp giúp bạn tự tay hoàn thành một bữa cơm đơn giản gồm trứng chiên hành lá vàng xốp, rau xào tỏi xanh giòn và nồi canh rau củ ngọt thanh. Bạn sẽ học cách sắp xếp thứ tự nấu hợp lý để các món ra bàn cùng lúc và còn nóng, cách nêm nếm lại trước khi tắt bếp, trình bày đĩa ăn gọn đẹp, cùng thói quen dọn rửa trong lúc nấu để bếp luôn sạch. Hoàn thành bài này, bạn đã đủ tự tin tự nấu một bữa cơm hoàn chỉnh cho mình và gia đình.', bai_tap = '[{"cau_hoi": "Bí quyết để rau xào giữ được màu xanh và độ giòn là gì?", "lua_chon": ["Xào lửa nhỏ và đậy nắp kín", "Xào lửa lớn, nhanh tay và không đậy nắp", "Cho thật nhiều nước vào chảo", "Xào rau trước khi chảo nóng"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Khi nấu nhiều món trong một bữa, nên bắt đầu từ món nào?", "lua_chon": ["Món nhanh nhất để xong sớm", "Món có thời gian nấu lâu nhất", "Món nào cũng được, không quan trọng", "Món tráng miệng trước"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Trứng chiên muốn xốp mềm thì nên làm thế nào?", "lua_chon": ["Đánh trứng thật kỹ và chiên trong chảo dầu đã nóng vừa", "Không đánh trứng, đập thẳng vào chảo lạnh", "Chiên lửa thật nhỏ trong 15 phút", "Cho nhiều nước vào trứng"], "dap_an_dung": 0, "diem": 10}]'::jsonb WHERE id = 'e79c9421-16ca-42a6-adbd-fc3d4a9776ed';
UPDATE bai_hoc SET tieu_de = 'Nước dùng phở: chọn xương, khử mùi và ninh nước trong', mo_ta = 'Bài học quan trọng nhất của khóa: xây dựng nồi nước dùng phở trong veo, ngọt thanh và thơm sâu. Bạn sẽ biết cách chọn xương ống và xương đuôi bò, chần xương bỏ nước đầu để khử mùi và loại bỏ bọt bẩn, nướng hành gừng và rang gia vị cho dậy mùi. Phần kỹ thuật ninh hướng dẫn giữ lửa liu riu, hớt bọt đúng lúc và thời điểm cho gia vị vào nồi để nước dùng không bị nồng hay đắng. Nắm vững bài này là bạn đã đi được nửa đường tới tô phở chuẩn vị.', bai_tap = '[{"cau_hoi": "Bước chần xương rồi đổ bỏ nước đầu có tác dụng gì?", "lua_chon": ["Giúp xương nhanh mềm hơn", "Loại bỏ máu, bọt bẩn và mùi hôi để nước dùng trong và thơm", "Giúp tiết kiệm ga khi ninh", "Làm xương có màu đẹp hơn"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Khi ninh nước dùng phở, nên giữ lửa như thế nào?", "lua_chon": ["Lửa lớn cho nước sôi bùng liên tục", "Lửa nhỏ, nước chỉ sôi liu riu", "Tắt bếp ủ kín suốt quá trình", "Lửa vừa và đậy nắp thật kín"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Gia vị rang (hồi, quế, thảo quả) nên cho vào nồi nước dùng vào thời điểm nào?", "lua_chon": ["Ngay từ khi bắt đầu ninh", "Sau 15 phút đầu", "Khoảng 45 phút cuối của quá trình ninh", "Khi đã tắt bếp hoàn toàn"], "dap_an_dung": 2, "diem": 10}]'::jsonb WHERE id = '3771c00f-45ae-4b1d-bf75-fe7d38126288';
UPDATE bai_hoc SET tieu_de = 'Sợi phở, thịt bò và nghệ thuật trụng bánh', mo_ta = 'Bài học xử lý hai nguyên liệu chính của tô phở: bánh phở và thịt bò. Bạn sẽ biết cách chọn bánh phở tươi sợi dai trong, kỹ thuật trụng nhanh 15-20 giây trong nước sôi để sợi mềm mà không nát, và cách xóc ráo nước để nước dùng không bị nhạt. Phần thịt bò hướng dẫn thái mỏng ngang thớ cho cả thịt chín và thịt tái, ướp nhẹ đúng cách, và nguyên lý chan nước dùng sôi già để thịt tái chín hồng vừa tới ngay trong tô.', bai_tap = '[{"cau_hoi": "Thái thịt bò đúng kỹ thuật cho món phở là thái như thế nào?", "lua_chon": ["Thái dọc theo thớ thịt", "Thái mỏng ngang thớ thịt", "Thái cục vuông lớn", "Băm nhuyễn rồi vo viên"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Trụng bánh phở quá lâu sẽ gây ra hậu quả gì?", "lua_chon": ["Sợi phở dai và ngon hơn", "Không ảnh hưởng gì", "Sợi phở bị nát, bở và làm đục nước dùng", "Sợi phở chuyển màu vàng đẹp"], "dap_an_dung": 2, "diem": 10}, {"cau_hoi": "Thịt bò tái trong tô phở chín được là nhờ đâu?", "lua_chon": ["Nhờ sức nóng của nước dùng sôi già chan trực tiếp lên thịt", "Nhờ trụng thịt trước 10 phút", "Nhờ hơi nóng của bánh phở", "Thịt tái không cần chín"], "dap_an_dung": 0, "diem": 10}]'::jsonb WHERE id = 'e900fdb1-9bf6-4da9-a787-41167154be4d';
UPDATE bai_hoc SET tieu_de = 'Hoàn thiện tô phở chuẩn vị và các món bún nước phổ biến', mo_ta = 'Bài cuối khóa đưa bạn đến khâu hoàn thiện như một quán phở chuyên nghiệp: tráng tô nóng, thứ tự xếp bánh - thịt - rau thơm, chan nước dùng đúng lượng và nêm lại lần cuối trước khi bưng ra. Bạn cũng sẽ được giới thiệu những lỗi thường gặp khiến tô phở mất điểm như nước dùng bị nhạt vì bánh phở còn đẫm nước, rau thơm cho quá sớm bị úa. Cuối bài là phần mở rộng nguyên tắc chung để áp dụng sang bún thang, bún mọc và các món bún nước khác.', bai_tap = '[{"cau_hoi": "Vì sao nên tráng tô bằng nước nóng trước khi xếp bánh phở?", "lua_chon": ["Để tô sạch hơn", "Để giữ nhiệt, giúp tô phở nóng lâu và thịt tái chín đều", "Để bánh phở không dính tô", "Chỉ là thói quen trang trí"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Thứ tự xếp tô phở nào sau đây đúng chuẩn?", "lua_chon": ["Rau thơm, bánh phở, thịt, nước dùng", "Bánh phở, thịt, rau thơm và hành, chan nước dùng sôi", "Nước dùng, bánh phở, rau thơm, thịt", "Thịt, nước dùng, bánh phở, rau thơm"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Nguyên tắc chung của các món bún nước ngon là gì?", "lua_chon": ["Nước dùng càng béo càng ngon", "Nước dùng trong và vừa vị, các thành phần sơ chế riêng rồi ráp lại khi ăn", "Nấu chung tất cả nguyên liệu từ đầu", "Càng nhiều gia vị bột càng thơm"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = 'dea712ee-b233-460f-bb77-4051b82ea3a4';
UPDATE bai_hoc SET tieu_de = 'Nhập môn làm bánh: nguyên liệu, dụng cụ và cách đọc công thức', mo_ta = 'Bài mở đầu giúp bạn bước vào thế giới làm bánh một cách bài bản: phân biệt các loại bột mì theo hàm lượng protein, vai trò của trứng, bơ, sữa, đường và các chất tạo nở như bột nở, muối nở. Bạn sẽ biết những dụng cụ tối thiểu cần có như cân điện tử, âu trộn, phới và khuôn, cùng cách đọc và chuẩn bị một công thức bánh (mise en place) trước khi bắt tay. Làm bánh là bộ môn của sự chính xác, và bài này cho bạn nền tảng chính xác đó.', bai_tap = '[{"cau_hoi": "Bột mì làm bánh bông lan khác bột mì làm bánh mì chủ yếu ở điểm nào?", "lua_chon": ["Màu sắc của bột", "Hàm lượng protein thấp hơn nên bánh mềm xốp hơn", "Giá thành rẻ hơn", "Không có sự khác biệt"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Điểm khác nhau cơ bản giữa bột nở (baking powder) và muối nở (baking soda) là gì?", "lua_chon": ["Hai thứ hoàn toàn giống nhau", "Muối nở cần môi trường axit để hoạt động, bột nở đã chứa sẵn thành phần axit", "Bột nở chỉ dùng cho bánh mặn", "Muối nở dùng để tạo màu"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Vì sao làm bánh cần cân đong nguyên liệu chính xác bằng cân?", "lua_chon": ["Để bánh trông chuyên nghiệp hơn", "Vì tỉ lệ nguyên liệu quyết định cấu trúc bánh, ước lượng dễ làm bánh hỏng", "Để rửa ít dụng cụ hơn", "Không cần thiết, ước lượng là đủ"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = 'e34a83b7-541b-4962-b479-f5a46b82758a';
UPDATE bai_hoc SET tieu_de = 'Kỹ thuật trộn bột, đánh trứng và kiểm soát lò nướng', mo_ta = 'Bài học kỹ thuật cốt lõi của người làm bánh: đánh trứng đạt độ bông đúng chuẩn, trộn bột theo phương pháp fold nhẹ nhàng để giữ bọt khí, và nhận biết hậu quả của việc trộn quá tay khiến bánh bị chai, dai. Phần lò nướng hướng dẫn làm nóng lò trước, đọc vị trí khay, hiểu chênh lệch nhiệt độ của lò gia đình và các dấu hiệu nhận biết bánh chín như mặt bánh đàn hồi, thành bánh tách nhẹ khỏi khuôn và tăm xiên khô sạch.', bai_tap = '[{"cau_hoi": "Trộn bột quá tay (overmix) thường khiến bánh bị làm sao?", "lua_chon": ["Bánh nở cao và xốp hơn", "Bánh bị chai, dai do gluten phát triển quá mức", "Bánh thơm hơn", "Không ảnh hưởng gì"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Vì sao phải làm nóng lò nướng trước khi cho bánh vào?", "lua_chon": ["Để tiết kiệm điện", "Để nhiệt độ trong lò ổn định và đúng mức khi bánh bắt đầu nở", "Để khuôn bánh nóng lên trước", "Chỉ cần thiết với bánh mì"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Dấu hiệu nào cho thấy bánh bông lan đã chín?", "lua_chon": ["Mặt bánh còn ướt bóng", "Xiên tăm vào giữa bánh rút ra thấy khô sạch, mặt bánh ấn nhẹ có độ đàn hồi", "Bánh có màu càng sậm càng tốt", "Nghe tiếng xèo xèo trong lò"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = '73dee13d-8982-4ab7-aa32-e45bbea497eb';
UPDATE bai_hoc SET tieu_de = 'Thực hành bánh bông lan cơ bản và trang trí đơn giản', mo_ta = 'Bài thực hành hoàn chỉnh: bạn tự làm một chiếc bánh bông lan cơ bản từ khâu cân nguyên liệu, đánh trứng, fold bột, đổ khuôn đến nướng và kiểm tra độ chín. Bài học chỉ ra các lỗi thường gặp ở mẻ bánh đầu tay như bánh xẹp sau khi ra lò, mặt bánh nứt hay đáy bánh chai, kèm cách khắc phục cho lần sau. Cuối bài là gợi ý trang trí đơn giản với đường bột, trái cây tươi và kem tươi đánh bông, cùng cách bảo quản để bánh giữ độ mềm ẩm.', bai_tap = '[{"cau_hoi": "Vì sao nên để trứng ở nhiệt độ phòng trước khi đánh bông?", "lua_chon": ["Để trứng đỡ tanh", "Trứng nhiệt độ phòng đánh bông nhanh và ổn định hơn", "Để trứng có màu đẹp hơn", "Không có lý do gì"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Động tác fold bột đúng kỹ thuật nhằm mục đích gì?", "lua_chon": ["Trộn bột thật nhanh cho đều", "Giữ lại bọt khí trong trứng đã đánh bông để bánh nở xốp", "Làm bột dai và chắc hơn", "Giúp bột không dính âu"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Bánh bông lan bị xẹp ngay sau khi lấy ra khỏi lò thường do nguyên nhân nào?", "lua_chon": ["Nướng quá lâu ở nhiệt cao", "Bánh chưa chín kỹ bên trong hoặc thay đổi nhiệt độ đột ngột", "Dùng quá ít đường", "Khuôn bánh quá nhỏ"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = 'f2fbd258-1eee-49a0-8a9b-45dd1b16adda';
UPDATE bai_hoc SET tieu_de = 'Ăn chay đủ chất: đạm thực vật và gia vị chay thiết yếu', mo_ta = 'Bài học nền tảng cho người nấu món chay: xây dựng khẩu phần đủ đạm từ đậu hũ, các loại đậu hạt, nấm và ngũ cốc nguyên hạt, thay vì lo lắng món chay thiếu chất. Bạn sẽ biết các gia vị tạo vị ngọt và umami tự nhiên cho món chay như nấm hương khô, rong biển, củ quả nướng và nước tương ngon, cùng tủ gia vị chay thiết yếu nên có sẵn. Bài học cũng gợi ý cách kết hợp nhóm thực phẩm để bữa chay cân bằng và no lâu.', bai_tap = '[{"cau_hoi": "Nhóm thực phẩm nào là nguồn đạm thực vật tiêu biểu cho món chay?", "lua_chon": ["Khoai tây và bắp", "Đậu hũ, đậu lăng, đậu gà và các loại đậu hạt", "Chỉ có rau xanh lá", "Trái cây tươi"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Nguyên liệu nào giúp món chay có vị umami đậm đà tự nhiên?", "lua_chon": ["Đường trắng tinh luyện", "Nấm hương khô và rong biển", "Giấm ăn", "Bột mì"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Kết hợp nhóm thực phẩm nào giúp bữa chay đủ axit amin thiết yếu hơn?", "lua_chon": ["Chỉ ăn một loại đậu duy nhất", "Kết hợp ngũ cốc với các loại đậu hạt trong ngày", "Chỉ ăn trái cây", "Uống nhiều nước"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = 'dc9910ee-81bd-4526-b8be-2aa3d74d8d50';
UPDATE bai_hoc SET tieu_de = 'Kỹ thuật chế biến món chay đậm đà: kho, xào và nấu canh', mo_ta = 'Bài học kỹ thuật giúp món chay thoát khỏi tiếng nhạt nhẽo: chiên hoặc áp chảo đậu hũ và nấm trước khi kho để thấm vị và giữ form, tạo lớp vị nền bằng hành boa-rô phi thơm và gia vị rang, kho nhỏ lửa cho sốt sánh bóng. Phần xào hướng dẫn lửa lớn nhanh tay để rau củ giữ màu và độ giòn, phần nấu canh gợi ý dùng nước dùng rau củ tự ninh từ vỏ bắp, củ cải và nấm để canh ngọt thanh tự nhiên mà không cần bột ngọt.', bai_tap = '[{"cau_hoi": "Trước khi kho, chiên sơ đậu hũ có tác dụng gì?", "lua_chon": ["Làm đậu hũ mềm và nát hơn", "Giúp đậu hũ giữ form, thấm sốt tốt và thơm hơn", "Chỉ để đẹp màu", "Không có tác dụng gì"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Nước dùng chay ngọt thanh tự nhiên có thể ninh từ nguyên liệu nào?", "lua_chon": ["Chỉ dùng nước lọc và muối", "Vỏ bắp, củ cải trắng, cà rốt và nấm hương", "Nước luộc thịt để dành", "Chỉ dùng đường phèn"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Xào rau củ chay ngon cần lưu ý điều gì?", "lua_chon": ["Xào lửa nhỏ thật lâu cho mềm nhũn", "Lửa lớn, chảo nóng, xào nhanh tay và nêm sau cùng", "Cho rau vào chảo lạnh rồi mới bật bếp", "Đậy nắp kín trong suốt quá trình xào"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = '71df9576-74eb-4515-bc99-616cb65645a8';
UPDATE bai_hoc SET tieu_de = 'Thực hành mâm cơm chay thanh đạm cho cả gia đình', mo_ta = 'Bài thực hành tổng kết: lên thực đơn và nấu trọn một mâm cơm chay cân bằng gồm món kho đậm đà, món xào tươi giòn, nồi canh thanh mát và cơm trắng, đủ chất cho 4 người ăn. Bạn sẽ học cách phân bổ thời gian nấu để các món hoàn thành cùng lúc, phối màu sắc cho mâm cơm bắt mắt và trình bày trang nhã đúng tinh thần thanh đạm. Bài học còn gợi ý thực đơn chay luân phiên trong tuần và cách tận dụng nguyên liệu thừa cho bữa sau.', bai_tap = '[{"cau_hoi": "Một mâm cơm chay cân bằng thường gồm những thành phần nào?", "lua_chon": ["Chỉ một món kho duy nhất", "Món kho, món xào, món canh và cơm, đủ nhóm chất", "Toàn món chiên rán", "Chỉ rau luộc và cơm"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Khi nấu mâm cơm nhiều món, nên phân bổ thời gian thế nào?", "lua_chon": ["Nấu từng món rời rạc không cần kế hoạch", "Bắt đầu món lâu chín trước, sơ chế chung một lượt, món nhanh làm sau cùng", "Nấu món canh cuối cùng mới bắc bếp", "Chiên tất cả mọi thứ trước"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Mâm cơm chay ngon và hấp dẫn nên chú ý yếu tố nào ngoài hương vị?", "lua_chon": ["Càng nhiều món càng tốt", "Phối hợp màu sắc và kết cấu giòn - mềm đa dạng", "Chỉ dùng một màu trắng", "Không cần trình bày"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = 'f657e044-b500-41ef-be03-65cdc194e948';
UPDATE bai_hoc SET tieu_de = 'Dao chuyên nghiệp: chọn dao, cầm dao và mài dao đúng cách', mo_ta = 'Bài học về công cụ quan trọng nhất của đầu bếp: con dao. Bạn sẽ biết cách chọn dao đầu bếp (chef knife) phù hợp tay và nhu cầu, kỹ thuật cầm dao pinch grip chuẩn để cắt nhanh, đều và an toàn, cùng các đường cắt cơ bản của bếp chuyên nghiệp. Phần mài dao phân biệt rõ mài bằng đá để lấy lại lưỡi bén và dùng thanh mài để nắn thẳng lưỡi, kèm tần suất bảo dưỡng hợp lý. Một con dao bén và đôi tay đúng kỹ thuật sẽ thay đổi hoàn toàn tốc độ làm bếp của bạn.', bai_tap = '[{"cau_hoi": "Kỹ thuật cầm dao pinch grip là cầm như thế nào?", "lua_chon": ["Nắm chặt toàn bộ cán dao bằng cả bàn tay", "Ngón cái và ngón trỏ kẹp vào hai bên sống dao ngay sát cán, các ngón còn lại ôm cán", "Chỉ cầm bằng ba ngón tay", "Đặt ngón trỏ dọc theo sống dao"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Vì sao nói dao cùn nguy hiểm hơn dao bén?", "lua_chon": ["Dao cùn nặng hơn", "Dao cùn dễ trượt khỏi nguyên liệu và phải dùng nhiều lực, dễ gây tai nạn", "Dao cùn làm thực phẩm xấu màu", "Dao cùn khó rửa hơn"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Thanh mài dao (honing rod) có vai trò gì?", "lua_chon": ["Thay thế hoàn toàn việc mài dao bằng đá", "Nắn thẳng lại lưỡi dao bị lệch trong quá trình sử dụng, không tạo lưỡi mới", "Dùng để cắt thực phẩm cứng", "Dùng để trang trí gian bếp"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = '62054ea4-ec7c-47ac-8556-f50e32c7c7db';
UPDATE bai_hoc SET tieu_de = 'Kiểm soát nhiệt: làm chủ chảo, lửa và thời điểm cho nguyên liệu', mo_ta = 'Bài học về kỹ năng phân biệt đầu bếp giỏi: kiểm soát nhiệt. Bạn sẽ hiểu phản ứng Maillard tạo lớp vỏ xém vàng thơm ngon, vì sao phải làm nóng chảo đúng mức trước khi cho dầu và nguyên liệu, và vì sao nguyên liệu ướt mặt hay cho quá nhiều vào chảo khiến món ăn bị luộc thay vì xém. Bài học hướng dẫn đọc dấu hiệu nhiệt bằng mắt và tai, chọn mức lửa theo từng giai đoạn nấu, và thời điểm vàng để cho nguyên liệu vào chảo cho món xào, áp chảo đạt chuẩn nhà hàng.', bai_tap = '[{"cau_hoi": "Phản ứng Maillard trong nấu ăn là gì?", "lua_chon": ["Phản ứng làm cháy khét thức ăn", "Phản ứng giữa đạm và đường ở nhiệt cao tạo lớp vỏ vàng nâu và hương thơm đậm", "Phản ứng làm tan chảy bơ", "Phản ứng lên men của bột"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Cho quá nhiều nguyên liệu vào chảo cùng lúc gây ra điều gì?", "lua_chon": ["Món ăn chín nhanh và ngon hơn", "Nhiệt chảo giảm mạnh, nguyên liệu ra nước và bị luộc thay vì xém vàng", "Tiết kiệm thời gian nêm nếm", "Không ảnh hưởng gì"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Vì sao nên để thịt nghỉ vài phút sau khi áp chảo hoặc nướng?", "lua_chon": ["Để thịt nguội bớt cho dễ cắt", "Để nước thịt phân bổ lại đều trong miếng thịt, cắt ra không bị chảy nước và khô", "Để thịt tiếp tục cháy xém", "Chỉ là thói quen của đầu bếp"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = '5d321226-f762-4023-a361-41dbeb265a9e';
UPDATE bai_hoc SET tieu_de = 'Tổ chức bếp như đầu bếp nhà hàng: mise en place và ra món', mo_ta = 'Bài học về tư duy tổ chức của bếp chuyên nghiệp: mise en place - mọi nguyên liệu được sơ chế, cân đong và xếp đúng vị trí trước khi bật bếp, giúp quá trình nấu trơn tru và không còn cảnh vừa nấu vừa chạy đi tìm gia vị. Bạn sẽ học cách đọc và chia nhỏ một công thức thành các bước chuẩn bị, nêm nếm xuyên suốt quá trình thay vì chỉ nêm ở cuối, giữ nóng và trình bày đĩa ăn có chủ đích. Đây là kỹ năng biến một người nấu ăn ngon thành một người nấu ăn ổn định như nhà hàng.', bai_tap = '[{"cau_hoi": "Mise en place trong bếp chuyên nghiệp có nghĩa là gì?", "lua_chon": ["Tên một loại dao của Pháp", "Mọi nguyên liệu và dụng cụ được chuẩn bị, sơ chế sẵn và đặt đúng vị trí trước khi nấu", "Cách bày đĩa ăn kiểu Pháp", "Một loại nước sốt nền"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Đầu bếp chuyên nghiệp nêm nếm món ăn theo cách nào?", "lua_chon": ["Chỉ nêm một lần duy nhất ở cuối", "Nêm và nếm thử xuyên suốt các giai đoạn nấu để điều chỉnh dần", "Không nêm, để khách tự nêm", "Nêm thật mặn ngay từ đầu"], "dap_an_dung": 1, "diem": 10}, {"cau_hoi": "Khi ra nhiều món cùng lúc cho một bàn ăn, nguyên tắc quan trọng là gì?", "lua_chon": ["Món nào xong trước mang ra trước bất kể các món còn lại", "Lên kế hoạch để các món hoàn thành gần như đồng thời và còn nóng khi ra bàn", "Chỉ cần món chính ngon là đủ", "Giữ món đầu tiên trong lò thật lâu chờ món cuối"], "dap_an_dung": 1, "diem": 10}]'::jsonb WHERE id = '11af415b-19b6-4158-854a-404b76152b93';

COMMIT;
